    /**
     * Handles create a Person.  if not key provided, calls create, otherwise calls save
     * @param		Person	person
     * @return		Person 
     */
	@PostMapping("/create")
    public Person create( @RequestBody(required=true) CreatePersonCommand command ) {
    	Person entity = null;

		entity = service.createPerson( command );
		LOGGER.info( "Successfully created Person with Id " + entity.getPersonId()  );

		return entity;
    }

    /**
     * Handles updating a Person.  if no key provided, calls create, otherwise calls save
     * @param		Person person
     * @return		Person
     */
	@PutMapping("/update")
    public Person update( @RequestBody(required=true) UpdatePersonCommand command ) {
		Person entity = null;

		entity = service.updatePerson(command);
		LOGGER.info( "Successfully updated Person with Id " + command.getPersonId()  );

		return entity;
	}
 
    /**
     * Handles deleting a Person entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeletePersonCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted Person with Id " + command.getPersonId()  );
	}
	
    /**
     * Handles loading a Person using a UUID
     * @param		UUID uuid 
     * @return		Person
     */    
    @GetMapping("/load")
    public Person load( @RequestParam(required=true) UUID uuid ) {
    	Person entity = service.getPerson( new PersonFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded Person with Id " + uuid   );

        return entity;
    }

